// Loads the model manifest (public/models-manifest.json, generated by
// scripts/fetch-models.mjs). This is the single source of truth for the model
// selector: the same file lists every served artifact, pins its sha256, and is
// what the service worker uses to pick the per-model cache bucket.

import type { ModelManifestEntry, ModelsManifest } from './types';

/** Fails fast so callers can show a real error instead of an empty dropdown. */
export async function fetchModelsManifest(): Promise<ModelsManifest> {
  const res = await fetch('/models-manifest.json', { cache: 'no-store' });
  if (!res.ok) {
    throw new Error(`Model manifest unavailable (HTTP ${res.status}). Run "npm run fetch-models".`);
  }
  const manifest = (await res.json()) as ModelsManifest;
  if (!Array.isArray(manifest.models) || manifest.models.length === 0) {
    throw new Error('Model manifest lists no models. Run "npm run fetch-models".');
  }
  return manifest;
}

export function defaultModelId(models: ModelManifestEntry[]): string {
  return models.find((m) => m.default)?.id ?? models[0]?.id;
}

/** Resolves ?model=<id-or-leaf> against the manifest, or null when unknown. */
export function resolveModelParam(
  models: ModelManifestEntry[],
  param: string | null,
): ModelManifestEntry | null {
  if (!param) return null;
  const needle = param.trim();
  return (
    models.find((m) => m.id === needle) ??
    models.find((m) => m.file.split('/').pop() === needle) ??
    null
  );
}